#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;class Observer{public:virtual~Observer()=default;virtual void onEvent(const string&)=0;};class Logger:public Observer{public:void onEvent(const string&m)override{cout<<"[EVENT] "<<m<<'\n';ofstream("smart_home.log",ios::app)<<m<<'\n';}};class SmartDevice{protected:int id;string name,room;bool power=false;double energy=0;public:SmartDevice(int i,string n,string r):id(i),name(move(n)),room(move(r)){}virtual~SmartDevice()=default;int getId()const{return id;}const string&getRoom()const{return room;}virtual string type()const=0;void turnOn(){power=true;}void turnOff(){power=false;}void tick(){if(power)energy+=.1;}virtual string state()const{return power?"ON":"OFF";}double usage()const{return energy;}void show()const{cout<<id<<" | "<<type()<<" | "<<name<<" | "<<room<<" | "<<state()<<" | energy "<<energy<<'\n';}};class SmartLight:public SmartDevice{int brightness=100;public:using SmartDevice::SmartDevice;string type()const override{return"Light";}string state()const override{return SmartDevice::state()+" brightness="+to_string(brightness);}};class SmartAC:public SmartDevice{double temp=24;public:using SmartDevice::SmartDevice;string type()const override{return"AC";}string state()const override{return SmartDevice::state()+" temp="+to_string(temp);}};class SmartDoor:public SmartDevice{bool locked=true;public:using SmartDevice::SmartDevice;string type()const override{return"Door";}string state()const override{return locked?"LOCKED":"UNLOCKED";}};class Camera:public SmartDevice{public:using SmartDevice::SmartDevice;string type()const override{return"Camera";}};class Sensor{protected:string room;public:Sensor(string r):room(move(r)){}virtual~Sensor()=default;virtual string type()const=0;virtual double read()=0;const string&getRoom()const{return room;}};class TemperatureSensor:public Sensor{public:using Sensor::Sensor;string type()const override{return"Temperature";}double read()override{double v;cout<<"Temperature: ";cin>>v;return v;}};class MotionSensor:public Sensor{public:using Sensor::Sensor;string type()const override{return"Motion";}double read()override{double v;cout<<"Motion 1/0: ";cin>>v;return v;}};struct Rule{string sensorType,room;double threshold;int deviceId;};class Home{vector<shared_ptr<SmartDevice>>devices;vector<shared_ptr<Sensor>>sensors;vector<Rule>rules;shared_ptr<Observer>log=make_shared<Logger>();shared_ptr<SmartDevice>find(int id){for(auto&d:devices)if(d->getId()==id)return d;return{};}public:Home(){devices.push_back(make_shared<SmartLight>(1,"Living Light","Living"));devices.push_back(make_shared<SmartAC>(2,"Living AC","Living"));devices.push_back(make_shared<SmartDoor>(3,"Door","Entrance"));devices.push_back(make_shared<Camera>(4,"Camera","Entrance"));sensors.push_back(make_shared<TemperatureSensor>("Living"));sensors.push_back(make_shared<MotionSensor>("Entrance"));rules.push_back({"Temperature","Living",28,2});rules.push_back({"Motion","Entrance",.5,4});}void list()const{for(auto&d:devices)d->show();}void control(){int id,on;cin>>id>>on;if(auto d=find(id)){on?d->turnOn():d->turnOff();log->onEvent("Manual device "+to_string(id));}}void rule(){Rule r;cin>>r.sensorType>>r.room>>r.threshold>>r.deviceId;rules.push_back(r);}void cycle(){for(auto&s:sensors){double v=s->read();log->onEvent(s->type()+"="+to_string(v));for(auto&r:rules)if(r.sensorType==s->type()&&r.room==s->getRoom()&&v>r.threshold)if(auto d=find(r.deviceId))d->turnOn();}for(auto&d:devices)d->tick();}void report()const{double t=0;for(auto&d:devices)t+=d->usage();cout<<"Energy "<<t<<'\n';}void run(){for(;;){cout<<"\nSmart Home\n1 Devices 2 Control 3 Add rule 4 Sensor cycle 5 Energy 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)list();else if(c==2)control();else if(c==3)rule();else if(c==4)cycle();else if(c==5)report();}}};int main(){Home{}.run();}
